						shift(_this.dieuHuongT1, -80, 0); shift(_this.dieuHuongT2, -80, 0);
						shift(_this.right_panel, 400, 0); shift(_this.nguonNangLuong, 400, 0);
						shift(_this.rud_LeftRight, -80, 0); shift(_this.left_panel, -80, 0);
						
