						shift(_this.HDSD, -200, 0);
						shift(_this.huongDanMoMay, -400, 0);
						shift(dInfo, -375, 0); dInfo.gotoAndStop(0); // 1->0
						shift(_this.dieuHuongP1, -400, 0); shift(_this.dieuHuongP2, -400, 0);
						shift(_this.right_panel, -400, 0); shift(_this.nguonNangLuong, -400, 0);
