		            if(panel.nutAnKD_2DC) panel.nutAnKD_2DC.addEventListener("click", function(e) { cheDoQuyTrinh = "2DC"; buocQuyTrinh = 1; daKichHoatTayDau_Trai = false; batDauKhoiDong_DC_Trai(null); if (!_this.manHinhChinh.hasEventListener("tick")) _this.manHinhChinh.addEventListener("tick", kiemTraQuyTrinhTuDong); });
