		// Thiết lập cấu hình Menu
		function setup_tombol_expand(tgt, frame_stop, jumlah_tombol) {
		    if (!tgt) {
		        console.warn("🚨 LỖI: Không tìm thấy Menu!");
		        return;
		    }
		
		    tgt.gotoAndStop(0); // Frame trong JS bắt đầu từ 0
		    tgt.frame_stop = frame_stop;
		    tgt.jumlah_tombol = jumlah_tombol;
		    tgt.isMenuOpen = false;
		
		    // Ẩn các nút con ban đầu
		    for (var i = 1; i <= jumlah_tombol; i++) {
		        var tombol = tgt.getChildByName("tombol_" + i);
		        if (tombol) {
		            tombol.visible = false;
		            tombol.cursor = "pointer";
		            tombol.on("click", atur_tombol_expand);
		        }
		    }
		
		    tgt.cursor = "pointer";
		    tgt.on("click", klik_expand);
		}
		
		function atur_tombol_expand(e) {
		    // 1. Dừng sự kiện click để không lan ra các đối tượng khác
		    e.stopPropagation(); 
		    
		    var nama_tombol = e.currentTarget.name;
		    var menuParent = e.currentTarget.parent; // Lưu lại thằng cha trước khi Reset
		    
		    onResetAppClick();
		    
		    // Gọi kịch bản
		    if (nama_tombol === "tombol_1") { playScenarioWithLog("KT_Nguon_MD"); }
		    else if (nama_tombol === "tombol_2") { playScenarioWithLog("KT_Nguon_AQ"); }
		    else if (nama_tombol === "tombol_3") { playScenarioWithLog("KT_Truoc_KD"); }
		    else if (nama_tombol === "tombol_4") { playScenarioWithLog("KD_DC"); }
		
		    // 2. Ép menu đóng và ẩn
		    close_menu(menuParent);
		}
		
		function klik_expand(e) {
		    var ob = e.currentTarget;
		    if (!ob.isMenuOpen) {
		        ob.isMenuOpen = true;
		        // Chạy animation expand
		        createjs.Tween.get(ob).to({/* Logic nếu cần di chuyển */}, 300).call(function() {
		            ob.gotoAndStop(ob.frame_stop - 1);
		            for (var i = 1; i <= ob.jumlah_tombol; i++) {
		                var tombol = ob.getChildByName("tombol_" + i);
		                if (tombol) tombol.visible = true;
		            }
		        });
		    }
		}
		
		function close_menu(ob) {
		    if (!ob) return;
		    ob.isMenuOpen = false;
		    
		    // Ép dừng mọi animation đang chạy trên Menu để nó không "cãi lệnh"
		    createjs.Tween.removeTweens(ob);
		    
		    // Ẩn các nút con
		    for (var i = 1; i <= ob.jumlah_tombol; i++) {
		        var tombol = ob.getChildByName("tombol_" + i);
		        if (tombol) {
		            tombol.visible = false; 
		        }
		    }
		    
		    // Ép về frame đóng và dừng hẳn ở đó
		    ob.gotoAndStop(0); 
		}
		// Khởi tạo (Đảm bảo tombol_menu đã tồn tại trên Stage)
		// Lưu ý: 10 trong AS3 thường tương đương frame 9 hoặc 10 trong JS tùy cách thiết kế
		setup_tombol_expand(this.tombol_menu, 10, 4);
		if (!this.isPanelStateInitialized) {
			let _this = this; // Tạo tham chiếu gốc an toàn
		
			// =============================================================
			// 1. CẤU HÌNH & TRẠNG THÁI (State Management)
			// =============================================================
			let tt = {
				rerum_lev: true,   // true = Đang tắt / Frame 0 (tương đương Frame 1 AS3)
				rerum_prav: true, 
				akum_lev: true,  
				akum_prav: true, 
				gen_lev: true,   
				gen_prav: true,  
				gen_vcy: true,   
				topl: true,      
				oxy: true,       
				nap_vcy: true,   
				nap_dc: true     
			};
		
			let akum_lev_code = 1;
			let akum_prav_code = 1;
		
			// =============================================================
			// 2. HÀM XỬ LÝ CHUNG (HELPER FUNCTIONS)
			// =============================================================
			let toggleSwitch = (btn, key) => {
				// Trong HTML5 dùng createjs.Sound để phát âm thanh
				createjs.Sound.play("Sound_CongTacClass");
				
				tt[key] = !tt[key]; // Đảo trạng thái
				btn.gotoAndStop(tt[key] ? 0 : 1); // 1: Tắt (Frame 0), 2: Bật (Frame 1)
				return tt[key]; 
			};
		
			let updateScreens = (childName, frame, requiredFrame = 7) => { // 8 AS3 -> 7 JS
				let screens = [_this.manHinhChinh.manHinhTrai, _this.manHinhChinh.manHinhGiua, _this.manHinhChinh.manHinhPhai];
				screens.forEach(s => {
					if (s && s.currentFrame == requiredFrame && s[childName]) {
						s[childName].gotoAndStop(frame);
					}
				});
			};
		
			let safeResetTimers = () => {
				try {
					let timers = [
						_this.myTimer_DC1_Trai, _this.myTimer_DC2_Trai, _this.myTimer_DC3_Trai, _this.myTimer_DC4_Trai, _this.myTimer_DC5_Trai,
						_this.myTimer_DC1_Phai, _this.myTimer_DC2_Phai, _this.myTimer_DC3_Phai, _this.myTimer_DC4_Phai, _this.myTimer_DC5_Phai
					];
					timers.forEach(t => { 
						if (t && typeof t.reset === "function") t.reset(); 
					});
				} catch(e) {}
			};
		
			// =============================================================
			// 3. XỬ LÝ CÁC NÚT CÔNG TẮC (LOGIC CHÍNH)
			// =============================================================
			let onRerumClick = (e) => {
				let btn = e.currentTarget;
				if (btn == _this.manHinhChinh.small_panel_right.rerum_zapus_lev) toggleSwitch(btn, "rerum_lev");
				else toggleSwitch(btn, "rerum_prav");
			};
		
			let setupAkum = (btn, key) => {
				btn.on("click", (e) => {
					let isOff = toggleSwitch(btn, key);
					
					if (isOff) { // Tắt
						if (_this.stopVCY) _this.stopVCY.gotoAndStop(0); // 1 AS3 -> 0 JS
						if (key == "akum_lev") akum_lev_code = 1; else akum_prav_code = 1;
						safeResetTimers();
					} else { // Bật
						if (key == "akum_lev") akum_lev_code = 0; else akum_prav_code = 0;
					}
		
					// Tắt màn hình nếu cả 2 pin đều tắt
					if (akum_lev_code + akum_prav_code == 2) {
						if (_this.manHinhChinh.manHinhTrai) _this.manHinhChinh.manHinhTrai.gotoAndStop(0);
						if (_this.manHinhChinh.manHinhGiua) _this.manHinhChinh.manHinhGiua.gotoAndStop(0);
						if (_this.manHinhChinh.manHinhPhai) _this.manHinhChinh.manHinhPhai.gotoAndStop(0);
					}
				});
			};
		
			let onGenClick = (e) => {
				let btn = e.currentTarget;
				let key = "";
				if (btn == _this.nguonNangLuong.congTacNguon.generator_lev) key = "gen_lev";
				else if (btn == _this.nguonNangLuong.congTacNguon.generator_prav) key = "gen_prav";
				else key = "gen_vcy";
				toggleSwitch(btn, key);
			};
		
			let onToplClick = (e) => toggleSwitch(e.currentTarget, "topl");
			let onOxyClick = (e) => toggleSwitch(e.currentTarget, "oxy");
		
			let onNapClick = (e) => {
				let btn = e.currentTarget;
				let isVCY = (btn == _this.manHinhChinh.small_panel_right.napAnKD_VCY);
				let key = isVCY ? "nap_vcy" : "nap_dc";
				
				let isOff = toggleSwitch(btn, key);
				
				if (isVCY) {
					_this.manHinhChinh.small_panel_right.nutAnKD_VCY.visible = !isOff;
				} else {
					let v = !isOff;
					_this.manHinhChinh.small_panel_right.nutAnKD_DC.visible = v;
					_this.manHinhChinh.small_panel_right.nutAnKD_DC_Trai.visible = v;
					_this.manHinhChinh.small_panel_right.nutAnKD_DC_Phai.visible = v;
				}
			};
		
			// =============================================================
			// HÀM ĐỒNG BỘ TRẠNG THÁI (TỰ ĐỘNG CẬP NHẬT KHI CHUYỂN TRANG)
			// =============================================================
			let syncVisualsLoop = (e) => {
				if (!_this.manHinhChinh) return;
				let screens = [_this.manHinhChinh.manHinhTrai, _this.manHinhChinh.manHinhGiua, _this.manHinhChinh.manHinhPhai];
				
				screens.forEach(s => {
					if (!s) return;
		
					// --- 1. ĐỒNG BỘ MÁY PHÁT (Chỉ xử lý khi màn hình ở Frame 7 - tương đương 8 AS3) ---
					if (s.currentFrame == 7) {
						setChildFrame(s, "mayPhat_DC_Trai", tt.gen_lev ? 0 : 1);
						setChildFrame(s, "mayPhat_DC_Phai", tt.gen_prav ? 0 : 1);
						setChildFrame(s, "mayPhat_VCY",   tt.gen_vcy ? 0 : 1);
					}
		
					// --- 2. ĐỒNG BỘ BƠM NHIÊN LIỆU (Chỉ xử lý khi màn hình ở Frame 4 - tương đương 5 AS3) ---
					if (s.currentFrame == 4) {
						setChildFrame(s, "bomNLDay", tt.topl ? 0 : 1);
						setChildFrame(s, "bomNLKD",  tt.topl ? 0 : 1);
					}
				});
			};
		
			_this.on("tick", syncVisualsLoop); // tick tương đương ENTER_FRAME
		
			let setChildFrame = (parentMC, childName, frame) => {
				let child = parentMC[childName] || parentMC.getChildByName(childName); 
				if (child && typeof child.gotoAndStop === "function") {
					if (child.currentFrame != frame) child.gotoAndStop(frame);
				}
			};
		
			// =============================================================
			// 4. XỬ LÝ MÀN HÌNH CHÍNH
			// =============================================================
			let xuLyNutAnManHinh = (viTriManHinh) => {
				if (!viTriManHinh) return;
				viTriManHinh.gotoAndStop(0); // 1 AS3 -> 0 JS
		
				if (viTriManHinh.btn_kiss) {
					viTriManHinh.btn_kiss.removeAllEventListeners("click"); 
					viTriManHinh.btn_kiss.on("click", (e) => {
						viTriManHinh.gotoAndStop(3); // 4 AS3 -> 3 JS
						setupScreenButtons(viTriManHinh);
					});
				}
			};
		
			let setupScreenButtons = (mc) => {
				// Tất cả frame đích đã được TRỪ ĐI 1 so với code gốc AS3
				let btnConfig = [
					{id: "btn_dvig", frame: 1}, {id: "btn_topl", frame: 4},
					{id: "btn_gidr", frame: 5}, {id: "btn_czo",  frame: 6},
					{id: "btn_cec",  frame: 7}, {id: "btn_kcy",  frame: 8},
					{id: "btn_pil",  frame: 34}, {id: "btn_nvg", frame: 35}, 
					{id: "btn_ito",  frame: 36}
				];
		
				btnConfig.forEach(item => {
					if (mc[item.id]) {
						mc[item.id].removeAllEventListeners("click");
						mc[item.id].on("click", () => mc.gotoAndStop(item.frame));
					}
				});
			};
		
			// Reset màn hình khi bấm Akum
			if (_this.nguonNangLuong && _this.nguonNangLuong.congTacNguon) {
				let akums = [_this.nguonNangLuong.congTacNguon.akum_prav, _this.nguonNangLuong.congTacNguon.akum_lev];
				akums.forEach(ak => {
					if(ak) {
						ak.on("click", () => {
							// Lùi 1 frame: 21->20, 8->7, 4->3
							if (_this.manHinhChinh.manHinhTrai) _this.manHinhChinh.manHinhTrai.gotoAndStop(20);
							if (_this.manHinhChinh.manHinhGiua) _this.manHinhChinh.manHinhGiua.gotoAndStop(7);
							if (_this.manHinhChinh.manHinhPhai) _this.manHinhChinh.manHinhPhai.gotoAndStop(3);
						});
					}
				});
			}
		
			// =============================================================
			// 5. XỬ LÝ ĐÈN CẢNH BÁO (DÙNG MẢNG)
			// =============================================================
			let xuLycacNutCanhBao = () => {
				let lights = [
					_this.manHinhChinh.denBaoHongTapTrung, _this.manHinhChinh.denBaoHong_CDY,
					_this.manHinhChinh.denBaoHong_Gidr, _this.manHinhChinh.pajar_kran_levOut.pajar_lamp_lev,
					_this.manHinhChinh.pajar_kran_levOut.pajar_kran_lev, _this.manHinhChinh.pajar_kran.pajar_lamp_prav,
					_this.manHinhChinh.pajar_kran.pajar_kran_prav, _this.manHinhChinh.small_panel_right.dapLua_BCY
				];
		
				lights.forEach(l => { if(l) l.gotoAndStop(0); }); // 1 AS3 -> 0 JS
		
				if (_this.manHinhChinh.kontron_lamp) {
					_this.manHinhChinh.kontron_lamp.on("mousedown", (e) => {
						lights.forEach(l => { if(l) l.play(); });
					});
					// Dùng pressup tốt hơn mouseup để bắt trường hợp người dùng nhả chuột ở ngoài nút
					_this.manHinhChinh.kontron_lamp.on("pressup", (e) => { 
						lights.forEach(l => { if(l) l.gotoAndStop(0); }); // 1 AS3 -> 0 JS
					});
				}
			};
		
			// =============================================================
			// 6. KHỞI TẠO & GÁN LISTENER (MAIN)
			// =============================================================
			
			let initObjects = [
				_this.manHinhChinh.small_panel_right.rerum_zapus_lev, _this.manHinhChinh.small_panel_right.rerum_zapus_prav,
				_this.nguonNangLuong.congTacNguon.akum_lev, _this.nguonNangLuong.congTacNguon.akum_prav,
				_this.nguonNangLuong.congTacNguon.generator_lev, _this.nguonNangLuong.congTacNguon.generator_prav,
				_this.nguonNangLuong.congTacNguon.generator_vcy, _this.nguonNangLuong.congTacNguon.kislorod_oxy,
				_this.nguonNangLuong.congTacNguon.topl_nasos, _this.manHinhChinh.small_panel_right.napAnKD_VCY,
				_this.manHinhChinh.small_panel_right.napAnKD_DC
			];
		
			initObjects.forEach(obj => {
				if (obj) {
					obj.gotoAndStop(0); // Set frame 1 -> 0
					obj.cursor = "pointer"; // Thay thế cho buttonMode = true
				}
			});
		
			let hiddenBtns = [
				_this.manHinhChinh.small_panel_right.nutAnKD_VCY, _this.manHinhChinh.small_panel_right.nutAnKD_DC,
				_this.manHinhChinh.small_panel_right.nutAnKD_DC_Trai, _this.manHinhChinh.small_panel_right.nutAnKD_DC_Phai,
				_this.manHinhChinh.small_panel_right.nutAnKD_VCY_2DC, _this.manHinhChinh.small_panel_right.nutAnKD_2DC
			];
			hiddenBtns.forEach(hb => { if(hb) hb.visible = false; });
		
			// Gán sự kiện Click
			_this.manHinhChinh.small_panel_right.rerum_zapus_lev.on("click", onRerumClick);
			_this.manHinhChinh.small_panel_right.rerum_zapus_prav.on("click", onRerumClick);
		
			setupAkum(_this.nguonNangLuong.congTacNguon.akum_lev, "akum_lev");
			setupAkum(_this.nguonNangLuong.congTacNguon.akum_prav, "akum_prav");
		
			_this.nguonNangLuong.congTacNguon.generator_lev.on("click", onGenClick);
			_this.nguonNangLuong.congTacNguon.generator_prav.on("click", onGenClick);
			_this.nguonNangLuong.congTacNguon.generator_vcy.on("click", onGenClick);
		
			_this.nguonNangLuong.congTacNguon.topl_nasos.on("click", onToplClick);
			_this.nguonNangLuong.congTacNguon.kislorod_oxy.on("click", onOxyClick);
		
			_this.manHinhChinh.small_panel_right.napAnKD_VCY.on("click", onNapClick);
			_this.manHinhChinh.small_panel_right.napAnKD_DC.on("click", onNapClick);
		
			// Khởi chạy
			if (_this.manHinhChinh) {
				xuLyNutAnManHinh(_this.manHinhChinh.manHinhGiua);
				xuLyNutAnManHinh(_this.manHinhChinh.manHinhTrai);
				xuLyNutAnManHinh(_this.manHinhChinh.manHinhPhai);
			}
			xuLycacNutCanhBao();
		
			this.isPanelStateInitialized = true; // Chốt cờ khởi tạo
		}
