				if (_this.huongDanMoMay && _this.huongDanMoMay.area_info) {
					_this.huongDanMoMay.area_info.gotoAndStop(13); // 14 -> 13
				}
				click_chuyen_slider(14, 14);
		
				if (_this.home_btn) _this.home_btn.visible = true;
